export function ProductCard({ product, onSelect }) {
  return (
    <div className="card" onClick={() => onSelect(product.id)}>
      <img src={product.image} className="thumb" />
      <h3>{product.name}</h3>
      <a href="#" className="more">Details</a>
      <input type="number" min={1} defaultValue={1} />
    </div>
  );
}

